ALTER TABLE "Premises" ADD CONSTRAINT "FK_Premises_Users_ResponsibleUserId" FOREIGN KEY ("ResponsibleUserId") REFERENCES "Users" ("Id") ON DELETE SET NULL;

ALTER TABLE "Readings" ADD CONSTRAINT "FK_Readings_Users_SubmittedById" FOREIGN KEY ("SubmittedById") REFERENCES "Users" ("Id") ON DELETE RESTRICT;

